package uk.ac.ravensbourne.casevault.security;
import java.util.*; import org.springframework.security.core.*; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.userdetails.UserDetails; import uk.ac.ravensbourne.casevault.domain.UserAccount;
/** Carries server-derived identity and tenant scope; never trust equivalent browser values (CWE-639). */
public record UserPrincipal(UUID id, UUID organisationId, String email, String password, String role, boolean enabled, boolean locked) implements UserDetails { public static UserPrincipal from(UserAccount u){return new UserPrincipal(u.getId(),u.getOrganisation().getId(),u.getEmail(),u.getPasswordHash(),u.getRole().name(),u.isEnabled(),u.isLocked());} @Override public Collection<? extends GrantedAuthority> getAuthorities(){return List.of(new SimpleGrantedAuthority("ROLE_"+role));} @Override public String getUsername(){return email;} @Override public String getPassword(){return password;} @Override public boolean isAccountNonLocked(){return !locked;} @Override public boolean isEnabled(){return enabled;} }
